<script setup>
import { computed, onMounted, reactive, ref } from "vue";
import ProfileScreen from "./components/ProfileScreen.vue";
import JobScreen from "./components/JobScreen.vue";
import AnalysisScreen from "./components/AnalysisScreen.vue";
import MatchScreen from "./components/MatchScreen.vue";
import GenerationScreen from "./components/GenerationScreen.vue";
import { loadDraft, saveDraft } from "./lib/profileStore";
import { buildContextPackage, normalizeWhitespace, validationMessage } from "./lib/contextPackage";
import { migrateProfile, newProfile } from "./lib/profileModel";
const stage = ref("profile"), profile = reactive(newProfile()), job = reactive({ url: "", description: "", normalizedDescription: "" });
const saved = ref(false), saving = ref(false), pdfStatus = ref(""), pdfError = ref(""), extractingPdf = ref(false), error = ref(""), analysisStatus = ref(""), match = ref(null), confirmed = ref(false), documents = ref(null), generationStatus = ref(""), generating = ref(false), outputDirectory = ref("exports");
const provider = ref("fake"), cli = ref("codex"), endpoint = ref(""), model = ref(""), apiKey = ref("");
const stages = [{ id: "profile", label: "Perfil" }, { id: "job", label: "Vaga" }, { id: "analysis", label: "Análise" }, { id: "match", label: "Resultado" }, { id: "generation", label: "Gerar" }];
const context = computed(() => buildContextPackage(profile, job));
function config() { return provider.value === "fake" ? { kind: "fake" } : provider.value === "cli" ? { kind: "cli", cli: cli.value } : { kind: "byok", endpoint: endpoint.value, model: model.value, apiKey: apiKey.value }; }
async function persist() { saving.value = true; saved.value = false; try { await saveDraft({ profile: JSON.parse(JSON.stringify(profile)), job: JSON.parse(JSON.stringify(job)), stage: stage.value }); saved.value = true; } finally { saving.value = false; } }
async function request(task, options) { const response = await fetch("http://127.0.0.1:4317/v1/execute", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ task, context: context.value, provider: config(), options }) }); const result = await response.json(); if (!response.ok) throw new Error(result.error || "A bridge recusou a solicitação."); return result; }
async function importPdf(file) { if (!file) return; pdfError.value = ""; extractingPdf.value = true; try { const { extractPdfText } = await import("./lib/pdfText"); const result = await extractPdfText(file); profile.confirmedEvidence = result.text; profile.importedSources = [{ type: "pdf", filename: file.name, extractedText: result.text, reviewedAt: new Date().toISOString() }]; pdfStatus.value = `${file.name} foi lido localmente. Revise e complemente as evidências abaixo.`; await persist(); } catch (cause) { pdfError.value = cause.message; } finally { extractingPdf.value = false; } }
async function analyze() { error.value = validationMessage(profile, job); if (error.value) return; job.normalizedDescription = normalizeWhitespace(job.description); stage.value = "analysis"; analysisStatus.value = "Enviando somente o pacote revisado à bridge local…"; try { const result = await request("evaluate"); match.value = result.output; confirmed.value = false; documents.value = null; await persist(); stage.value = "match"; } catch (cause) { error.value = cause.message; stage.value = "job"; } }
async function generate() { generating.value = true; generationStatus.value = "Gerando documentos a partir de evidências confirmadas…"; try { const result = await request("generate", { language: "pt-BR", coverLetter: true, additionalInstructions: "" }); documents.value = result.output; generationStatus.value = "Documentos prontos para revisão."; } catch (cause) { generationStatus.value = cause.message; } finally { generating.value = false; } }
async function exportApplication() { if (!documents.value) return; generationStatus.value = "Criando pasta local da candidatura…"; try { const response = await fetch("http://127.0.0.1:4317/v1/export", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ outputDirectory: outputDirectory.value, jobTitle: job.url || job.description.slice(0, 80), documents: documents.value, context: context.value, evaluation: match.value }) }); const result = await response.json(); if (!response.ok) throw new Error(result.error); generationStatus.value = `Candidatura exportada em ${result.directory}.`; } catch (cause) { generationStatus.value = cause.message; } }
onMounted(async () => { const draft = await loadDraft(); if (!draft) return; Object.assign(profile, migrateProfile(draft.profile)); if (draft.job) Object.assign(job, draft.job); });
</script>
<template><q-layout class="app-shell"><q-header class="header"><q-toolbar><div class="logo">T</div><q-toolbar-title>Tailor Match AI</q-toolbar-title><q-chip icon="lock" square>Local-first</q-chip></q-toolbar></q-header><q-page-container><q-page class="page"><main><header class="hero"><p class="eyebrow">CARREIRA COM EVIDÊNCIA</p><h1>Uma candidatura precisa, sem inventar sua história.</h1><p>Perfil local, vaga, análise e documentos em um fluxo claro.</p></header><ol class="progress" aria-label="Progresso"><li v-for="item in stages" :key="item.id" :class="{ active: stage === item.id, done: stages.findIndex((x) => x.id === item.id) < stages.findIndex((x) => x.id === stage) }">{{ item.label }}</li></ol><ProfileScreen v-if="stage === 'profile'" :profile="profile" :saving="saving" :saved="saved" :pdf-status="pdfStatus" :pdf-error="pdfError" :extracting-pdf="extractingPdf" @save="persist" @next="stage = 'job'; persist()" @import-pdf="importPdf"/><JobScreen v-else-if="stage === 'job'" :job="job" :provider="provider" :cli="cli" :endpoint="endpoint" :model="model" :api-key="apiKey" :running="false" :error="error" @update:provider="provider = $event" @update:cli="cli = $event" @update:endpoint="endpoint = $event" @update:model="model = $event" @update:api-key="apiKey = $event" @back="stage = 'profile'" @analyze="analyze"/><AnalysisScreen v-else-if="stage === 'analysis'" :status="analysisStatus" :error="error" @back="stage = 'job'"/><MatchScreen v-else-if="stage === 'match'" :match="match" :confirmed="confirmed" @update:confirmed="confirmed = $event" @back="stage = 'job'" @next="stage = 'generation'"/><GenerationScreen v-else :documents="documents" :running="generating" :status="generationStatus" :output-directory="outputDirectory" @update:output-directory="outputDirectory = $event" @back="stage = 'match'" @generate="generate" @export="exportApplication"/></main></q-page></q-page-container></q-layout></template>
<style>
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;700&family=Space+Grotesk:wght@500;600;700&display=swap');
:root{font-family:'DM Sans',sans-serif;color:#1e1b4b;background:#faf5ff}.app-shell{min-height:100dvh;background:linear-gradient(135deg,#faf5ff,#fff)}.header{background:#fff;color:#1e1b4b;border-bottom:1px solid #ddd6fe}.header .q-toolbar{max-width:1120px;margin:auto}.logo{display:grid;place-items:center;width:32px;height:32px;margin-right:10px;border-radius:8px;background:#1e1b4b;color:white;font-weight:700}.page{max-width:1040px;margin:auto;padding:48px 20px 88px}.hero{max-width:700px;margin:0 auto 32px;text-align:center}.eyebrow{margin:0 0 8px;color:#7c3aed;font-size:11px;font-weight:700;letter-spacing:.12em}.hero h1,.screen h1,.screen h2,strong{font-family:'Space Grotesk',sans-serif}.hero h1{margin:0;font-size:clamp(36px,6vw,58px);line-height:1.05;letter-spacing:-.055em}.hero p:last-child,.screen-heading p{color:#475569;line-height:1.65}.progress{display:flex;justify-content:center;gap:8px;padding:0;margin:0 0 24px;list-style:none}.progress li{padding:8px 12px;border-radius:99px;color:#64748b;font-size:13px}.progress .active{background:#ede9fe;color:#5b21b6;font-weight:700}.progress .done{color:#047857}.screen{padding:40px;border:1px solid #ddd6fe;background:#fff;box-shadow:0 18px 42px rgba(76,29,149,.07)}.screen-heading{display:flex;justify-content:space-between;gap:20px;margin-bottom:30px}.screen h1{margin:0;font-size:32px;letter-spacing:-.04em}.screen h2{font-size:20px}.choice-grid,.result-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.choice-card{display:grid;gap:10px;min-height:200px;padding:28px;border:1px solid #ddd6fe;background:#fff;color:#1e1b4b;text-align:left;cursor:pointer}.choice-card:hover{border-color:#7c3aed;background:#faf8ff}.choice-card .q-icon{font-size:32px;color:#7c3aed}.choice-card strong{font-size:20px}.choice-card span{color:#475569;line-height:1.55}.upload-card{display:grid;grid-template-columns:auto 1fr;gap:22px;padding:30px;background:#faf8ff;border:1px dashed #a78bfa}.upload-card>.q-icon{font-size:42px;color:#7c3aed}.notice{margin:18px 0}.success{background:#ecfdf5;color:#065f46}.error{background:#fff1f2;color:#b91c1c}.form-section{margin-top:30px;padding-top:24px;border-top:1px solid #ede9fe}.section-title,.screen-actions{display:flex;align-items:center;justify-content:space-between;gap:16px}.identity-grid{display:grid;grid-template-columns:auto 1fr 1fr;gap:16px;align-items:center}.repeat-row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr)) auto;gap:12px;margin:12px 0}.repeat-card{padding:16px;margin:12px 0;background:#fafaff;border:1px solid #ede9fe}.repeat-card .repeat-row{grid-template-columns:repeat(2,minmax(0,1fr)) auto}.screen-actions{margin-top:32px;padding-top:20px;border-top:1px solid #ede9fe}.advanced{display:grid;gap:12px;padding:12px 16px}.job-input{margin-top:18px}.analysis{text-align:center}.analysis .q-spinner{margin:40px 0 16px}.score-panel{display:grid;grid-template-columns:180px 1fr;gap:28px;padding:28px;background:#1e1b4b;color:#fff}.score-panel span{display:block;font-size:11px;letter-spacing:.1em}.score-panel strong{font-size:64px}.score-panel small{font-size:18px}.result-item{display:flex;gap:10px;padding:12px 0;border-bottom:1px solid #ede9fe}.result-item p{margin:4px 0;color:#475569;line-height:1.5}.radar-table{margin-top:18px}.radar-table table{width:100%;border-collapse:collapse}.radar-table th,.radar-table td{padding:10px;text-align:left;border-bottom:1px solid #ede9fe}.generation-options{display:grid;gap:16px;margin-bottom:24px}.document-preview{margin:20px 0;border:1px solid #ddd6fe}.document-preview h2{padding:0 16px}.document-preview pre{margin:0;padding:16px;background:#17142e;color:#e9e7ff;white-space:pre-wrap;overflow:auto}@media(max-width:700px){.screen{padding:24px 18px}.screen-heading,.screen-actions{align-items:flex-start;flex-direction:column}.choice-grid,.result-grid,.identity-grid,.repeat-row,.repeat-card .repeat-row,.score-panel{grid-template-columns:1fr}.progress{justify-content:flex-start;overflow:auto}.upload-card{grid-template-columns:1fr}.hero{text-align:left}}
</style>
